<template><div class="page-title">线索管理</div><div class="toolbar"><el-input v-model="keyword" placeholder="姓名或公司" @keyup.enter="load"/><el-button type="primary" @click="edit()">新增线索</el-button><el-button @click="load">查询</el-button></div><el-card><el-table :data="rows" stripe><el-table-column prop="name" label="姓名"/><el-table-column prop="company" label="公司"/><el-table-column prop="phone" label="电话"/><el-table-column prop="source" label="来源"/><el-table-column prop="status" label="状态"/><el-table-column label="操作"><template #default="{row}"><el-button link @click="edit(row)">编辑</el-button><el-button link type="success" :disabled="row.status==='CONVERTED'" @click="convert(row)">转化</el-button></template></el-table-column></el-table></el-card><el-dialog v-model="show" title="线索" width="500px"><el-form label-width="90px"><el-form-item label="姓名"><el-input v-model="form.name"/></el-form-item><el-form-item label="公司"><el-input v-model="form.company"/></el-form-item><el-form-item label="电话"><el-input v-model="form.phone"/></el-form-item><el-form-item label="邮箱"><el-input v-model="form.email"/></el-form-item></el-form><template #footer><el-button @click="show=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog><el-dialog v-model="convertShow" title="转化线索"><el-form label-width="100px"><el-form-item label="创建商机"><el-switch v-model="convertForm.createOpportunity"/></el-form-item><el-form-item v-if="convertForm.createOpportunity" label="商机名称"><el-input v-model="convertForm.opportunityName"/></el-form-item><el-form-item v-if="convertForm.createOpportunity" label="金额"><el-input v-model="convertForm.amount"/></el-form-item></el-form><template #footer><el-button @click="convertShow=false">取消</el-button><el-button type="primary" @click="doConvert">确认转化</el-button></template></el-dialog></template>
<script setup>import {ref,onMounted} from 'vue';import {leads} from '../api';import {ElMessage} from 'element-plus';const rows=ref([]),keyword=ref(''),show=ref(false),convertShow=ref(false),form=ref({}),convertForm=ref({createOpportunity:true,opportunityName:''}),current=ref(null);async function load(){const d=await leads.list({page:1,size:20,keyword:keyword.value});rows.value=d.records}function edit(x){form.value={...(x||{})};show.value=true}async function save(){if(form.value.id)await leads.update(form.value.id,form.value);else await leads.add(form.value);show.value=false;load()}function convert(x){current.value=x;convertForm.value={createOpportunity:true,opportunityName:x.name+'商机'};convertShow.value=true}async function doConvert(){await leads.convert(current.value.id,convertForm.value);ElMessage.success('转化成功');convertShow.value=false;load()}onMounted(load)</script>
